Output3[Expected Approach - 1] Using Binary Search - O(log n) Time and O(1) SpaceThe idea is to use the fact that the given array is sorted. We can apply binary search to find the index of the element greater than or equal to the target. Step By Step Implementation:Set variables lo and hi to the starting and ending of array.Find mid = (lo + hi) / 2 and compare arr[mid] with target=> if arr[mid] >= target, then lower bound will be in the range arr[lo...mid], so update result to mid and hi to mid - 1.=> if arr[mid] < target, then all elements in the range [lo...mid] will also be less than target, so update lo to mid + 1.Continue step 2 till lo <= hi.Return result as the lower bound.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int lowerBound(vector<int> &arr, int target) {
    int low = 0, high = arr.size() - 1; 
    int res = arr.size();

  	while(low <= high) {
      	int mid = low + (high - low)/2;

        // If arr[mid] >= target, then mid can be the
        // lower bound, so update res to mid and
        // search in left half, i.e. [lo...mid-1]
      	if(arr[mid] >= target) {
            res = mid;
            high = mid - 1;
        }

        // If arr[mid] < target, then lower bound
        // cannot lie in the range [lo...mid] so
        // search in right half, i.e. [mid+1...hi]
      	else {
            low = mid + 1;
        }
    }
  	return res;	
}

int main() {
    vector<int> arr = {2, 3, 7, 10, 11, 11, 25};
    int target = 9;

    cout << lowerBound(arr, target);
    return 0;
}


